import{_ as a,o as d,c as o,a2 as e}from"./chunks/framework.DGvnA5EY.js";const r="/workbuddy-guide/assets/01-video-gen.Ufcvpu79.png",q=JSON.parse('{"title":"第 19 章 一句话召唤 AI 视频团队","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 做视频最劝退的是\\"要会写脚本、会画、会剪、会配音\\"。WorkBuddy 可以把这支团队塞进 一句话里：你给主题，它出脚本、出画面、出成片。这一章带你跑通\\"从一句话到一段视频\\"…","frontmatter":{"title":"第 19 章 一句话召唤 AI 视频团队"},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 19 章 一句话召唤 AI 视频团队/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 19 章 一句话召唤 AI 视频团队/index.md","lastUpdated":1791615980000}'),l={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 19 章 一句话召唤 AI 视频团队/index.md"};function s(n,t,i,h,u,p){return d(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="第-19-章-一句话召唤-ai-视频团队" tabindex="-1">第 19 章 一句话召唤 AI 视频团队 <a class="header-anchor" href="#第-19-章-一句话召唤-ai-视频团队" aria-label="Permalink to &quot;第 19 章 一句话召唤 AI 视频团队&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）</p></blockquote><p>做视频最劝退的是&quot;要会写脚本、会画、会剪、会配音&quot;。WorkBuddy 可以把这支团队塞进 一句话里：你给主题，它出脚本、出画面、出成片。这一章带你跑通&quot;从一句话到一段视频&quot;， 并示范怎么用 <code>skill-creator</code> <strong>零代码</strong>把你的视频风格固化成专属技能。</p><p><img src="'+r+`" alt="一只小黑站在一个写着&#39;视频&#39;的取景框后，框里冒出分镜、字幕和播放键" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;AI 视频&quot;，与实际软件界面无关。</em></p><h2 id="一、先想清楚-这支视频要交付什么" tabindex="-1">一、先想清楚：这支视频要交付什么 <a class="header-anchor" href="#一、先想清楚-这支视频要交付什么" aria-label="Permalink to &quot;一、先想清楚：这支视频要交付什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>要说清什么</th><th>示例</th></tr></thead><tbody><tr><td>目标</td><td>视频用来干嘛</td><td>抖音/视频号一条 12 秒口播短视频</td></tr><tr><td>受众</td><td>谁看</td><td>对 AI 感兴趣的小白</td></tr><tr><td>材料</td><td>已有素材/设定</td><td>固定主角&quot;小虎&quot;、知性幽默基调</td></tr><tr><td>格式</td><td>时长/比例/风格</td><td>12 秒、竖屏 9:16、氛围感场景</td></tr><tr><td>验收</td><td>怎么判断可用</td><td>脚本逻辑顺、画面不崩、字幕不乱</td></tr></tbody></table><h2 id="二、先选对-skill-ai-视频的组合" tabindex="-1">二、先选对 Skill：AI 视频的组合 <a class="header-anchor" href="#二、先选对-skill-ai-视频的组合" aria-label="Permalink to &quot;二、先选对 Skill：AI 视频的组合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式 / Skill</th><th>适合处理</th><th>本章怎么用</th><th>注意点</th></tr></thead><tbody><tr><td><strong>视频生成技能（如内置 VideoGen / 即梦 / 可灵类）</strong></td><td>文生视频、图生视频</td><td>脚本定稿后生成成片</td><td>需按官方文档开通相应能力</td></tr><tr><td><strong>图像生成技能</strong></td><td>分镜画面、封面、配图</td><td>先出关键帧再合成</td><td>风格要统一</td></tr><tr><td><strong>字幕 / 配音技能</strong></td><td>旁白朗读、加字幕</td><td>口语短句更自然</td><td>注意音色合规</td></tr><tr><td><strong>剪辑 / 合成</strong></td><td>拼镜头、加转场</td><td>出可发平台的成片</td><td>生成式视频仍需人工过一遍</td></tr><tr><td><strong>skill-creator（零成本）</strong></td><td>把视频风格固化</td><td>&quot;脱口秀文案&quot;做成专属技能</td><td>见第四节</td></tr></tbody></table><h2 id="三、真实可复制提示词" tabindex="-1">三、真实可复制提示词 <a class="header-anchor" href="#三、真实可复制提示词" aria-label="Permalink to &quot;三、真实可复制提示词&quot;">​</a></h2><h3 id="提示词-1-主题-→-分镜脚本-先看脚本-再生成" tabindex="-1">提示词 1｜主题 → 分镜脚本（先看脚本，再生成） <a class="header-anchor" href="#提示词-1-主题-→-分镜脚本-先看脚本-再生成" aria-label="Permalink to &quot;提示词 1｜主题 → 分镜脚本（先看脚本，再生成）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>做一条 12 秒的口播短视频，主题【为什么天是蓝的】，轻松口语风，给小白看。</span></span>
<span class="line"><span>先不要生成视频，给我 4 个分镜，每个分镜包含：</span></span>
<span class="line"><span>画面描述、镜头运动（0-4秒/5-8秒/9-12秒分别怎么动）、一句旁白台词、时长。</span></span>
<span class="line"><span>风格：场景要有氛围感（竹林/茶室/湖边/书房这种有画面感的），不要 low。</span></span>
<span class="line"><span>末尾加一条&quot;禁止出现&quot;清单：避免崩坏、避免文字乱码、避免人物变形。</span></span></code></pre></div><h3 id="提示词-2-脚本确认后生成画面与视频" tabindex="-1">提示词 2｜脚本确认后生成画面与视频 <a class="header-anchor" href="#提示词-2-脚本确认后生成画面与视频" aria-label="Permalink to &quot;提示词 2｜脚本确认后生成画面与视频&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基于上面的分镜脚本，生成对应的视频片段，竖屏 9:16，保持画风一致，</span></span>
<span class="line"><span>旁白用自然语言短句，生成后告诉我每段时长是否接近设定。</span></span></code></pre></div><h2 id="四、零成本-skill-用-skill-creator-把-脱口秀文案-固化-真实范例" tabindex="-1">四、零成本 Skill：用 skill-creator 把&quot;脱口秀文案&quot;固化（真实范例） <a class="header-anchor" href="#四、零成本-skill-用-skill-creator-把-脱口秀文案-固化-真实范例" aria-label="Permalink to &quot;四、零成本 Skill：用 skill-creator 把&quot;脱口秀文案&quot;固化（真实范例）&quot;">​</a></h2><p>这是社区里一个真实跑通的&quot;零代码造技能&quot;案例——主角&quot;小虎&quot;，51 岁 AI 讲师，做抖音和 视频号短视频，每条 12 秒左右、核心是输出一个金句。整个过程不用写代码，<strong>靠三轮对话 迭代</strong>就做出了专属技能：</p><ul><li><strong>第一轮｜说出需求</strong>：&quot;帮我做一个脱口秀文案的 skill。名字叫&#39;脱口秀文案&#39;，用途是以后 我直接说主题，它就能生成完整的视频提示词给我。主角小虎，51 岁 AI 讲师，平台抖音/视频号， 每条 12 秒左右，核心输出金句，场景要有氛围感。&quot;</li><li><strong>第二轮｜指出问题继续调</strong>：&quot;场景太笼统，要具体到竹林、茶室、湖边、书房；服装写清 春夏秋冬；镜头运动分时间段（0-3/4-8/9-12 秒）；加一条禁忌清单。你把这个 skill 更新一下。&quot;</li><li><strong>第三轮｜确认格式再优化</strong>：&quot;格式再优化：场景/服装/台词/镜头用【】括号区分；每组提示词 要有&#39;禁止出现&#39;项；场景要差异化，别 10 组都是室内。再出一版。&quot;</li></ul><p>最终定稿的技能文件，包含角色设定、每组输出固定模板（【主题与角度】【场景与服装】 【台词】【镜头】【禁止出现】），以后只说主题就能批量出可直接喂给视频工具的提示词。 <strong>这正是&quot;零成本&quot;的精髓：不花一分钱、不写一行代码，把你的创作 SOP 变成可复用工具。</strong></p><h2 id="五、执行步骤表" tabindex="-1">五、执行步骤表 <a class="header-anchor" href="#五、执行步骤表" aria-label="Permalink to &quot;五、执行步骤表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>WorkBuddy 做什么</th><th>你要确认什么</th></tr></thead><tbody><tr><td>1</td><td>出主题 + 分镜脚本（提示词 1）</td><td>脚本逻辑顺、禁忌清单合理</td></tr><tr><td>2</td><td>你确认脚本</td><td>镜头/台词/场景是否你要的</td></tr><tr><td>3</td><td>生成画面与视频（提示词 2）</td><td>画风一致、时长接近设定</td></tr><tr><td>4</td><td>你播放检查</td><td>字幕/画面有没有崩</td></tr></tbody></table><h2 id="六、实际效果与验收标准" tabindex="-1">六、实际效果与验收标准 <a class="header-anchor" href="#六、实际效果与验收标准" aria-label="Permalink to &quot;六、实际效果与验收标准&quot;">​</a></h2><p><strong>实际效果</strong>：一条竖屏短视频草稿，脚本经你审过、画面由 AI 生成。</p><p><strong>验收标准</strong>：</p><ul><li>[ ] 脚本逻辑通顺、旁白口语、禁忌清单覆盖常见翻车点</li><li>[ ] 成片画风一致、字幕不乱、时长接近设定</li><li>[ ] 你已在播放器里完整过一遍，崩的镜头已重生成</li></ul><h2 id="七、一个必须记住的坑" tabindex="-1">七、一个必须记住的坑 <a class="header-anchor" href="#七、一个必须记住的坑" aria-label="Permalink to &quot;七、一个必须记住的坑&quot;">​</a></h2><p><strong>生成式视频不一定一次成型。</strong> 画面可能错位、字幕可能乱、时长可能跑偏。把它当&quot;初剪 草稿&quot;，成片前你要在播放器里过一遍，必要时重生成某一镜。别直接拿出去发。另外，<strong>先审 脚本再生成</strong>，能少一大半返工——很多人失败在&quot;一上来就要成片&quot;。</p><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p><strong>分镜（Storyboard）</strong>：把视频按镜头拆开，每镜画什么、说什么先列清楚。</p><p><strong>竖屏 9:16</strong>：手机全屏的比例，短视频平台常用；横屏 16:9 偏&quot;视频网站&quot;。</p><p><strong>生成式视频</strong>：由 AI 根据文字/图片直接产出视频，不是剪辑现成素材。</p><p><strong>零成本 Skill</strong>：用 skill-creator 把你的视频风格/SOP 固化成专属技能，不写代码。</p></blockquote><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 用提示词 1 出一条 4 镜脚本并审一遍</li><li>[ ] 确认脚本后，生成一段短视频草稿并播放检查</li><li>[ ] （进阶）用 skill-creator 把你的视频风格固化成专属技能</li><li>[ ] 记下这次哪镜翻车，下次提示词里提前规避</li></ul><hr><p><em>下一篇：第 20 章——自媒体不只是靠努力，而是一条增长闭环。</em></p><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>`,34)])])}const b=a(l,[["render",s]]);export{q as __pageData,b as default};
